import {Search,MapPin,Heart,Compass,ArrowRight,Store,User,LayoutDashboard,Tag,BarChart3,Settings,ChevronRight,X,SlidersHorizontal,Navigation,Phone,Globe2,Clock3,ShieldCheck,RotateCcw,LogOut,Plus,Check,Sparkles,Utensils,House,ShoppingBag,Menu,ChevronDown,Trophy,Vote,CalendarDays,Lock} from "lucide-react";
import {activity,businesses,categories,cravings,newcomers,promotions,sideAds,teamTops,weeklyPoll,type Business,type Promotion,type PromoPeriod} from "@/lib/radar-data";
